function get(path){return path.split('.').reduce((o,k)=>o?.[k],copy[state.lang])}
function translate(){document.documentElement.lang=state.lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const v=get(el.dataset.i18n);if(v!==undefined)el.innerHTML=v});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const v=get(el.dataset.i18nPlaceholder);if(v!==undefined)el.placeholder=v});document.querySelectorAll('.language-switch span').forEach((x,i)=>x.classList.toggle('lang-active',(state.lang==='en'?i===0:i===1)));renderPath();renderAssessment();renderJobs();renderDynamicRoute();renderScene();window.UHRLocale?.apply(state.lang)}
function renderPath(){const d=(pathwayData[state.lang]||pathwayData.en)[state.path],experience=(pathwayExperience[state.lang]||pathwayExperience.en)[state.path],panel=document.querySelector('#pathway-panel');panel.dataset.path=state.path;panel.innerHTML=`<div class="pathway-main"><div class="pathway-live"><i></i><span>${experience.status}</span><b>${experience.code}</b></div><h3>${d.title}</h3><p>${d.body}</p><div class="pathway-capabilities">${d.items.map(x=>`<span>${x}</span>`).join('')}</div></div><div class="pathway-route"><small>DELIVERY SEQUENCE</small>${d.route.map((x,i)=>`<div class="route-step"><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span><i></i></div>`).join('')}</div><aside class="pathway-command"><small>GOVERNED OUTPUTS</small>${experience.outputs.map(x=>`<div><i>✓</i><span>${x}</span></div>`).join('')}<button type="button" class="button primary" data-pathway-action>${experience.action}</button><button type="button" class="pathway-explore" data-pathway-explore>View all capabilities</button></aside>`;panel.querySelector('[data-pathway-action]').onclick=()=>{if(experience.service)openNamedService(experience.service);else if(experience.target==='workplace')document.querySelector('#workplace')?.scrollIntoView({behavior:'smooth',block:'start'});else if(experience.target==='assessment')openModal('assessment');track('pathway_action',{path:state.path})};panel.querySelector('[data-pathway-explore]').onclick=()=>document.querySelector('#industries')?.scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelector('#language-select')?.addEventListener('change',e=>{state.lang=e.target.value;localStorage.setItem('uhr-lang',state.lang);translate()});document.querySelectorAll('[data-path]').forEach(b=>b.addEventListener('click',()=>{state.path=b.dataset.path;document.querySelectorAll('[data-path]').forEach(x=>x.setAttribute('aria-selected',x===b));renderPath()}));
const modals={assessment:document.querySelector('#assessment-modal'),consultation:document.querySelector('#consultation-modal'),service:document.querySelector('#service-request-modal'),login:document.querySelector('#login-modal'),application:document.querySelector('#application-modal')};let lastFocus;
function openModal(name){lastFocus=document.activeElement;const m=modals[name];m.hidden=false;document.body.style.overflow='hidden';m.querySelector('button,input,select')?.focus();if(name==='login')loadPortal()}
function closeModal(m){m.hidden=true;document.body.style.overflow='';lastFocus?.focus()}
