let mutationQueue=Promise.resolve();
async function apiRequest(path,options={}){
  const method=(options.method||'GET').toUpperCase();
  const mutating=!['GET','HEAD','OPTIONS'].includes(method);
  for(let attempt=0;attempt<2;attempt++){
    const headers=new Headers(options.headers||{});
    if(!headers.has('Content-Type'))headers.set('Content-Type','application/json');
    if(mutating){
      const verification=await fetch('/api/auth/csrf',{credentials:'same-origin',cache:'no-store'});
      const proof=await verification.json().catch(()=>({}));
      if(!verification.ok||typeof proof.csrf_token!=='string'||!proof.csrf_token)throw new Error('Unable to verify this request. Please reload and try again.');
      headers.set('X-CSRF-Token',proof.csrf_token);
    }
    const response=await fetch(path,{...options,method,credentials:'same-origin',headers});
    const data=await response.json().catch(()=>({}));
    // The gateway rejects this exact error before executing the business action.
    // Only that rejection may be retried; network/credential/business failures are not replayed.
    if(mutating&&attempt===0&&response.status===403&&data.error==='Request verification failed')continue;
    if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);
    return data;
  }
}
function api(path,options={}){
  if(['GET','HEAD','OPTIONS'].includes((options.method||'GET').toUpperCase()))return apiRequest(path,options);
  const request=mutationQueue.then(()=>apiRequest(path,options));
  mutationQueue=request.catch(()=>{});
  return request;
}
