const scenarioTheater=document.querySelector('#scenario-theater');
if(scenarioTheater){
  const scenarioObserver=new IntersectionObserver(([entry])=>{scenarioInView=entry.isIntersecting;if(scenarioInView)startScenarioRotation();else stopScenarioRotation()},{threshold:.35});
  scenarioObserver.observe(scenarioTheater);
  const suspendScenario=()=>{scenarioSuspended=true;stopScenarioRotation()};
  const resumeScenario=()=>{scenarioSuspended=false;startScenarioRotation()};
  scenarioTheater.addEventListener('mouseenter',suspendScenario);scenarioTheater.addEventListener('mouseleave',resumeScenario);
  scenarioTheater.addEventListener('focusin',suspendScenario);scenarioTheater.addEventListener('focusout',resumeScenario);
  scenarioTheater.addEventListener('pointermove',e=>{if(!sceneMotion)return;const r=scenarioTheater.getBoundingClientRect();scenarioTheater.style.setProperty('--scene-x',`${((e.clientX-r.left)/r.width-.5)*10}px`);scenarioTheater.style.setProperty('--scene-y',`${((e.clientY-r.top)/r.height-.5)*8}px`)});
  scenarioTheater.addEventListener('pointerleave',()=>{scenarioTheater.style.setProperty('--scene-x','0px');scenarioTheater.style.setProperty('--scene-y','0px')});
}
