const industryModels={care:{label:'Care delivery and regulated workforce',summary:'Coordinate credentials, staffing, safety, learning and service quality across distributed care environments.',services:['Recruiting & Executive Search','HRIS, ATS & People Operations','Global Safety Coordination','Urban Academy & Workforce Training']},industrial:{label:'Industrial workforce and production assurance',summary:'Connect skilled labor, workplace controls, operating readiness and performance evidence across plants and production networks.',services:['Staffing & Virtual Workforce','Compliance Audits & Corrective Action','Workforce Analytics','Project & Program Management']},field:{label:'Field risk and contractor operations',summary:'Govern mobilization, contractor readiness, site controls, corrective action and workforce accountability across active locations.',services:['Global Safety Coordination','Compliance Audits & Corrective Action','Staffing & Virtual Workforce','Project & Program Management']},logistics:{label:'Network workforce and movement control',summary:'Align staffing, shift readiness, safety, capacity and operational intelligence across moving networks.',services:['Workforce Analytics','Staffing & Virtual Workforce','Automation & Systems Integration','Global Safety Coordination']},regulated:{label:'Regulated people and business operations',summary:'Strengthen role governance, employee relations, controls, evidence and executive decision support.',services:['HR Strategy & Operating Model','Employee & Labor Relations','Company360 & KPI Management','Document & Template Factory']},digital:{label:'Digital talent and scalable operations',summary:'Build the people, systems, automation and performance infrastructure required for fast-changing digital organizations.',services:['HRIS, ATS & People Operations','Automation & Systems Integration','Recruiting & Executive Search','Company360 & KPI Management']},institution:{label:'Mission, public accountability and workforce service',summary:'Connect policy, workforce capability, learning, compliance and measurable service delivery.',services:['HR Strategy & Operating Model','Urban Academy & Workforce Training','Document & Template Factory','Company Intelligence Diagnostic']},distributed:{label:'Distributed customer and frontline workforce',summary:'Coordinate hiring, scheduling, training, engagement and operating consistency across many locations.',services:['Recruiting & Executive Search','Performance, Culture & Engagement','Urban Academy & Workforce Training','Workforce Analytics']},growth:{label:'Enterprise formation and scalable growth',summary:'Create the operating model, talent system, technology foundation and performance rhythm for the next stage.',services:['HR Strategy & Operating Model','Business Process & Digital Transformation','Recruiting & Executive Search','Company Intelligence Diagnostic']}};
function industryModelFor(name){const n=name.toLowerCase();if(/health|pharma|life science/.test(n))return industryModels.care;if(/manufactur|automotive|consumer|agriculture|food/.test(n))return industryModels.industrial;if(/construction|real estate|energy|oil|gas|mining|utilit/.test(n))return industryModels.field;if(/logistics|transport|aviation/.test(n))return industryModels.logistics;if(/financial|banking|insurance|professional/.test(n))return industryModels.regulated;if(/technology|saas|telecom|media|entertainment/.test(n))return industryModels.digital;if(/education|government|nonprofit|ngo/.test(n))return industryModels.institution;if(/hospitality|tourism|retail|commerce/.test(n))return industryModels.distributed;return industryModels.growth}
function renderIndustryWorkspace(industry){const root=document.querySelector('#industry-workspace');if(!root)return;const model=industryModelFor(industry),services=model.services.map(name=>capabilityCatalog.capabilities.find(item=>item.name===name)).filter(Boolean);root.hidden=false;root.innerHTML=`<div class="industry-workspace-copy"><span class="eyebrow">INDUSTRY OPERATING PATH</span><small>${model.label}</small><h4>${industry}</h4><p>${model.summary}</p><div class="industry-control-strip"><span>People</span><i></i><span>Risk</span><i></i><span>Operations</span><i></i><span>Intelligence</span></div></div><div class="industry-workspace-services"><small>Priority enterprise pathways</small><div></div><button type="button" class="button primary" data-industry-assess>Configure ${industry}</button></div>`;const serviceRoot=root.querySelector('.industry-workspace-services div');for(const service of services){const button=document.createElement('button');button.type='button';button.innerHTML=`<b>${service.name}</b><span>${service.description}</span>`;button.onclick=()=>openServiceRequest(service);serviceRoot.append(button)}root.querySelector('[data-industry-assess]').onclick=()=>{const select=document.querySelector('#need-industry');if(select)select.value=industry;const need=document.querySelector('#universal-intake-form textarea');if(need)need.value=`Enterprise ${industry} pathway: workforce, compliance, operations and intelligence`;document.querySelector('.hero-workbench')?.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>need?.focus(),450)};root.scrollIntoView({behavior:'smooth',block:'center'});track('industry_path_selected',{industry})}
function profileFor(item){const category=item?.category||'';if(category==='Safety & Compliance'||category==='Documents')return {key:'risk',...workflowProfiles.risk};if(category==='Talent & Staffing')return {key:'talent',...workflowProfiles.talent};if(category==='Business Systems'||category==='Technology')return {key:'systems',...workflowProfiles.systems};if(category==='Learning'||category==='Growth & Creative')return {key:'growth',...workflowProfiles.growth};return {key:'advisory',...workflowProfiles.advisory}}
let currentServiceStep=0,currentServiceTemplate=null,currentServiceItem=null;
function createServiceField(field){const label=document.createElement('label');if(field.type==='textarea')label.className='wide';const title=document.createElement('span');title.textContent=field.label;let input;if(field.type==='textarea'){input=document.createElement('textarea');input.maxLength=2000}else if(field.type==='select'){input=document.createElement('select');for(const value of field.options||[]){const option=document.createElement('option');option.value=value;option.textContent=value;input.append(option)}}else{input=document.createElement('input');input.type=field.type||'text';input.maxLength=field.type==='number'?64:500;if(field.min!==undefined)input.min=String(field.min);if(field.max!==undefined)input.max=String(field.max)}input.name=field.name;input.required=field.required===true;label.append(title,input);return label}
function renderServiceStep(){const form=document.querySelector('#service-request-form');form.querySelectorAll('[data-service-step]').forEach(section=>section.hidden=Number(section.dataset.serviceStep)!==currentServiceStep);document.querySelector('#service-step-back').hidden=currentServiceStep===0;document.querySelector('#service-step-next').hidden=currentServiceStep===2;document.querySelector('#service-request-submit').hidden=currentServiceStep!==2;document.querySelectorAll('#service-workflow-steps li').forEach((li,index)=>{li.classList.toggle('active',index===currentServiceStep);li.classList.toggle('complete',index<currentServiceStep)});if(currentServiceStep===2)renderServiceReview();document.querySelector('.service-workflow-main')?.scrollTo({top:0,behavior:'smooth'})}
function renderServiceReview(){const form=document.querySelector('#service-request-form'),root=document.querySelector('#service-request-review');root.replaceChildren();const rows=[...currentServiceTemplate.questions.map(field=>[field.label,form.elements[field.name]?.value||'—']),['Organization',form.elements.company.value||'—'],['Request owner',form.elements.name.value||'—'],['Work email',form.elements.email.value||'—'],['Jurisdiction',form.elements.country.value||'—']];for(const [label,value] of rows){const row=document.createElement('div'),key=document.createElement('span'),answer=document.createElement('b');key.textContent=label;answer.textContent=value;row.append(key,answer);root.append(row)}}
function serviceStepValid(){const section=document.querySelector(`[data-service-step="${currentServiceStep}"]`);for(const input of section.querySelectorAll('input,select,textarea'))if(!input.reportValidity())return false;return true}
document.querySelector('#service-step-next').addEventListener('click',()=>{if(!serviceStepValid())return;currentServiceStep=Math.min(2,currentServiceStep+1);renderServiceStep()});
document.querySelector('#service-step-back').addEventListener('click',()=>{currentServiceStep=Math.max(0,currentServiceStep-1);renderServiceStep()});
function openServiceRequest(item){const template=serviceTemplateCatalog.templates.find(x=>x.service===item.name);if(!template){const field=document.querySelector('#lead-form [name=need]');if(field)field.value=`Service qualification required: ${item.name}`;openModal('consultation');return}const form=document.querySelector('#service-request-form'),profile=profileFor(item);currentServiceTemplate=template;currentServiceItem=item;currentServiceStep=0;form.reset();form.dataset.workflow=profile.key;document.querySelector('.service-request-card').dataset.workflow=profile.key;form.elements.template_id.value=template.id;form.elements.template_version.value=serviceTemplateCatalog.version;form.elements.service.value=item.name;document.querySelector('#service-workflow-code').textContent=profile.code;document.querySelector('#service-workflow-type').textContent=`${profile.key.toUpperCase()} WORKFLOW`;document.querySelector('#service-workflow-name').textContent=profile.name;document.querySelector('#service-workflow-description').textContent=profile.description;document.querySelector('#service-workflow-steps').replaceChildren(...profile.steps.map((value,index)=>{const li=document.createElement('li');li.innerHTML=`<span>${String(index+1).padStart(2,'0')}</span><b>${value}</b>`;return li}));document.querySelector('#service-workflow-outputs').replaceChildren(...profile.outputs.map(value=>{const li=document.createElement('li');li.textContent=value;return li}));document.querySelector('#service-workflow-destination').textContent=`Destination: ${profile.destination}`;document.querySelector('#service-request-category').textContent=item.category||'Service workflow';document.querySelector('#service-request-title').textContent=template.headline;document.querySelector('#service-request-intro').textContent=template.intro;document.querySelector('#service-request-submit').textContent=template.cta;document.querySelector('#service-request-governance').textContent=`${item.governance} · ${(item.delivery||[]).join(' · ')}`;const country=document.querySelector('#service-request-country');country.replaceChildren(...capabilityCatalog.jurisdictions.map(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;return option}));document.querySelector('#service-specific-fields').replaceChildren(...template.questions.map(createServiceField));form.querySelector('.form-status').textContent='';renderServiceStep();openModal('service');track('service_workflow_opened',{service:item.name,template_id:template.id,workflow:profile.key})}
function openNamedService(name){const item=capabilityCatalog.capabilities.find(x=>x.name===name);if(item)openServiceRequest(item);else openModal('consultation')}
document.querySelectorAll('[data-service-path]').forEach(button=>button.addEventListener('click',()=>openNamedService(button.dataset.servicePath)));
document.querySelector('#scene-action')?.addEventListener('click',()=>openNamedService(activeScene==='home-health'?'Recruiting & Executive Search':activeScene==='field'?'Global Safety Coordination':'Company360 & KPI Management'));
function catalogItem(type,item){const button=document.createElement('button');button.className='catalog-item';button.type='button';button.dataset.catalog=item.name;const profile=type==='service'?profileFor(item):null,kind=document.createElement('small'),name=document.createElement('b'),description=document.createElement('span');if(profile)button.dataset.workflow=profile.key;kind.textContent=type==='industry'?'Industry operating path':`${profile.code} · ${profile.name}`;name.textContent=item.name;description.textContent=item.description||(state.lang==='es'?'Ruta configurable de personas, riesgo, talento y desempeño.':'Open a purpose-built industry workspace for people, risk, operations and intelligence.');button.append(kind,name,description);if(item.delivery?.length){const delivery=document.createElement('em');delivery.textContent=item.delivery.slice(0,3).join(' · ');button.append(delivery)}button.onclick=()=>type==='industry'?renderIndustryWorkspace(item.name):openServiceRequest(item);return button}
function renderCatalog(){const root=document.querySelector('#catalog-results');if(!root)return;const q=(document.querySelector('#catalog-search')?.value||'').trim().toLowerCase(),items=[...capabilityCatalog.industries.map(name=>({type:'industry',item:{name}})),...capabilityCatalog.capabilities.map(item=>({type:'service',item}))].filter(({type,item})=>{const modeMatch=catalogMode==='all'||(catalogMode==='industry'&&type==='industry')||(type==='service'&&profileFor(item).key===catalogMode);return modeMatch&&`${item.name} ${item.category||''} ${item.description||''}`.toLowerCase().includes(q)});root.replaceChildren(...items.map(({type,item})=>catalogItem(type,item)));root.dataset.count=String(items.length)}
async function loadCapabilityCatalog(){try{const [catalogResponse,templateResponse]=await Promise.all([fetch('/api/catalog',{credentials:'same-origin'}),fetch('/api/service-intake-templates',{credentials:'same-origin'})]);if(!catalogResponse.ok||!templateResponse.ok)throw new Error('catalog unavailable');capabilityCatalog=await catalogResponse.json();serviceTemplateCatalog=await templateResponse.json();renderCatalog()}catch{const root=document.querySelector('#catalog-results');if(root)root.textContent=state.lang==='es'?'El catálogo no está disponible temporalmente.':'The capability catalog is temporarily unavailable.'}}
const filters=document.querySelector('#catalog-filters');if(filters){const modes=[['all','All'],['industry','Industries'],['advisory','01 Advisory'],['risk','02 Risk & Compliance'],['talent','03 Talent'],['systems','04 Systems'],['growth','05 Growth & Learning']];filters.setAttribute('role','tablist');filters.replaceChildren(...modes.map(([value,label],index)=>{const button=document.createElement('button');button.type='button';button.className=index?'':'active';button.dataset.filter=value;button.textContent=label;button.setAttribute('role','tab');button.setAttribute('aria-selected',String(index===0));return button}));filters.onclick=e=>{const selected=e.target.closest('[data-filter]');if(!selected)return;catalogMode=selected.dataset.filter;filters.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===selected);b.setAttribute('aria-selected',String(b===selected))});renderCatalog()};document.querySelector('#catalog-search').oninput=renderCatalog;loadCapabilityCatalog()}
/* Delegated binding survives locale/content refreshes that replace catalog controls. */
document.addEventListener('click',event=>{const selected=event.target.closest?.('#catalog-filters [data-filter]');if(!selected)return;const root=selected.closest('#catalog-filters');catalogMode=selected.dataset.filter;root.querySelectorAll('[data-filter]').forEach(button=>{const active=button===selected;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});renderCatalog()});
function analyticsSession(){let id=sessionStorage.getItem('uhr-session');if(!id){id=crypto.randomUUID();sessionStorage.setItem('uhr-session',id)}return id}
async function track(event,detail={}){if(localStorage.getItem('uhr-analytics')!=='yes')return;try{const region=localStorage.getItem('uhr-region')||Intl.DateTimeFormat().resolvedOptions().timeZone||'unknown';localStorage.setItem('uhr-region',region);await api('/api/analytics/events',{method:'POST',body:JSON.stringify({event,path:location.pathname+location.hash,language:state.lang,region,session_id:analyticsSession(),detail})})}catch{}}
async function loadActivity(){try{const r=await api('/api/analytics/public-summary');document.querySelector('#visit-count').textContent=r.visits;document.querySelector('#advice-count').textContent=r.advice;document.querySelector('#region-count').textContent=r.regions;document.querySelector('#service-count').textContent=r.services;document.querySelector('#activity-feed').innerHTML=r.feed.map(x=>`<div class="feed-event"><b>${x.label}</b><span>${x.region} · ${x.time}</span></div>`).join('');document.querySelectorAll('.map-pulse').forEach(x=>x.classList.remove('active'));for(const x of r.region_data||[]){const z=x.region.toLowerCase();const key=z.startsWith('america/')?(z.includes('sao_paulo')||z.includes('lima')||z.includes('bogota')?'sa':'na'):z.startsWith('europe/')?'eu':z.startsWith('africa/')?'af':z.startsWith('asia/')?'as':z.startsWith('australia/')||z.startsWith('pacific/')?'oc':'';if(key)document.querySelector(`.p-${key}`)?.classList.add('active')}}catch{}}
const banner=document.querySelector('#privacy-banner');if(localStorage.getItem('uhr-analytics'))banner.hidden=true;document.querySelector('#analytics-accept').onclick=()=>{localStorage.setItem('uhr-analytics','yes');banner.hidden=true;track('visit',{referrer:document.referrer?'external':'direct'});loadActivity()};document.querySelector('#analytics-decline').onclick=()=>{localStorage.setItem('uhr-analytics','no');banner.hidden=true};
if(localStorage.getItem('uhr-analytics')==='yes'){track('page_view',{title:document.title});setInterval(()=>track('heartbeat'),60000)}
document.querySelector('#advice-form').addEventListener('submit',async e=>{e.preventDefault();const out=document.querySelector('#advice-answer');out.textContent=state.lang==='es'?'Analizando y enrutando…':'Analyzing and routing…';try{const r=await api('/api/advice',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.currentTarget)),language:state.lang})});out.textContent=r.answer;track('advice_request',{industry:r.industry,service:r.service})}catch(err){out.textContent=err.message}});
document.querySelectorAll('[role="tablist"]').forEach(tablist=>tablist.addEventListener('keydown',event=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;const tabs=[...tablist.querySelectorAll('[role="tab"]')].filter(tab=>!tab.disabled);if(!tabs.length)return;const current=Math.max(0,tabs.indexOf(document.activeElement));let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:event.key==='ArrowRight'?(current+1)%tabs.length:(current-1+tabs.length)%tabs.length;event.preventDefault();tabs[next].focus();tabs[next].click()}));
const observer=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('visible',e.isIntersecting)),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>observer.observe(x));
const navLinks=[...document.querySelectorAll('.desktop-nav a[href^="#"]')];
const navSections=navLinks.map(link=>document.querySelector(link.getAttribute('href'))).filter(Boolean);
const navObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;navLinks.forEach(link=>link.toggleAttribute('aria-current',link.getAttribute('href')===`#${visible.target.id}`))},{rootMargin:'-28% 0px -58%',threshold:[0,.1,.35,.65]});
navSections.forEach(section=>navObserver.observe(section));
window.addEventListener('scroll',()=>document.querySelector('.site-header').dataset.elevated=String(scrollY>20),{passive:true});document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#language-select').value=state.lang;loadJobs();loadActivity();translate();

