const jurisdictionRoutes={
'north-america':{code:'NA',title:'North America',body:'Coordinate workforce, labor, privacy and workplace-safety pathways across United States, Canada and Mexico with country-specific validation.',services:['HR operating model and employee relations','OSHA / EHS and provincial safety pathways','Recruiting, mobility and workforce systems'],rule:'United States service paths can include OSHA / EHS. Canadian and Mexican requirements are routed for local legal and regulatory validation.',service:'OSHA / EHS United States'},
'central-america':{code:'CAC',title:'Central America & Caribbean',body:'Build consistent people operations while validating labor, social-security, privacy and safety obligations in each country or territory.',services:['Multi-country HR operations','Workforce compliance coordination','Talent, onboarding and learning'],rule:'Country and territory requirements differ substantially; every recommendation is scoped before implementation.',service:'Global Safety Coordination'},
'south-america':{code:'SA',title:'South America',body:'Connect HR, occupational safety, labor and workforce performance across South American operations with country-level governance.',services:['SG-SST Colombia and regional safety','Labor and employee-relations coordination','People analytics and workforce transformation'],rule:'Colombia routes can include SG-SST. Other jurisdictions require their own qualified local validation.',service:'SG-SST Colombia'},
'europe':{code:'EU',title:'Europe',body:'Coordinate workforce operating models across European markets while preserving local labor, consultation, privacy and safety boundaries.',services:['People governance and operating models','Workforce data and privacy coordination','Learning, talent and transformation'],rule:'EU-level frameworks do not replace national labor and safety requirements; local validation remains mandatory.',service:'HR Strategy & Operating Model'},
'asia':{code:'AS',title:'Asia',body:'Design scalable workforce, talent and operational controls across diverse labor markets and fast-changing growth environments.',services:['Market-entry workforce architecture','Talent acquisition and workforce planning','Systems, analytics and operating controls'],rule:'Asia is not treated as one legal market. Country-specific employment, data and safety rules are validated locally.',service:'HR Strategy & Operating Model'},
'africa':{code:'AF',title:'Africa',body:'Support workforce growth, capability and responsible operations across distinct national and regional environments.',services:['Workforce strategy and talent systems','Safety and operational readiness','Training and leadership capability'],rule:'National legal, labor and safety requirements must be confirmed by qualified local resources.',service:'Global Safety Coordination'},
'oceania':{code:'OC',title:'Australia & Oceania',body:'Coordinate people, safety and workforce-performance pathways across Australia, New Zealand and Pacific markets.',services:['Work health and safety coordination','HR operating model and talent','Performance, culture and learning'],rule:'Australia, New Zealand and Pacific jurisdictions are independently validated before advice is implemented.',service:'Global Safety Coordination'}
};
function renderJurisdiction(key='north-america'){
  const item=jurisdictionRoutes[key]||jurisdictionRoutes['north-america'],root=document.querySelector('#jurisdiction-live');if(!root)return;
  root.innerHTML=`<div><span class="region-code">${item.code}</span><h3>${item.title}</h3><p>${item.body}</p><div class="jurisdiction-services">${item.services.map(x=>`<span>${x}</span>`).join('')}</div><button type="button" class="button primary" data-jurisdiction-action>Configure this regional pathway</button></div><aside class="jurisdiction-rule"><b>Governance boundary</b><small>${item.rule}</small></aside>`;
  root.querySelector('[data-jurisdiction-action]').onclick=()=>{openNamedService(item.service);track('jurisdiction_path_selected',{region:key,service:item.service})};
}
document.querySelectorAll('[data-jurisdiction]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-jurisdiction]').forEach(x=>x.setAttribute('aria-selected',String(x===button)));renderJurisdiction(button.dataset.jurisdiction)}));

const mediaLibraries={
institutional:{code:'MEDIA-001',title:'Institutional film system',body:'A flagship story connected to service, industry and market variants—managed as controlled assets, not disconnected files.',meta:[['Master','16:9 · multilingual'],['Variants','Web · YouTube · events'],['Rights','Owner and consent record'],['Version','Approval-controlled']],steps:[['Brief','ready'],['Production','pending'],['Review','pending'],['Publication','pending']]},
academy:{code:'LEARN-001',title:'Academy & training library',body:'Role-aware onboarding, compliance, manager and capability learning with audience, outcome and completion metadata.',meta:[['Audience','Role and tenant aware'],['Learning','Outcome mapped'],['Evidence','Completion record'],['Review','SME + compliance']],steps:[['Learning brief','ready'],['SME review','ready'],['Approval','pending'],['Assignment','pending']]},
presentations:{code:'DECK-001',title:'Executive presentation center',body:'Governed client, leadership and proposal presentations with owner, purpose, confidentiality and expiration controls.',meta:[['Purpose','Executive decision'],['Access','Role restricted'],['Owner','Named custodian'],['Expiry','Review scheduled']],steps:[['Draft','ready'],['Quality review','ready'],['Approval','pending'],['Distribution','pending']]},
social:{code:'CHANNEL-001',title:'Controlled channel variants',body:'Approved derivatives for social and campaign channels linked back to the source master, rights record and publication history.',meta:[['Formats','16:9 · 9:16 · 1:1'],['Captions','Language tracked'],['Rights','Inherited + checked'],['History','Channel and date']],steps:[['Source master','ready'],['Derivative QA','ready'],['Approval','pending'],['Publish log','pending']]}
};
function renderMediaLibrary(key='institutional'){
  const item=mediaLibraries[key]||mediaLibraries.institutional,root=document.querySelector('#media-live');if(!root)return;
  root.innerHTML=`<div class="asset-record"><div><span class="eyebrow">${item.code}</span><h3>${item.title}</h3><p>${item.body}</p><div class="asset-meta">${item.meta.map(([a,b])=>`<span><b>${a}</b>${b}</span>`).join('')}</div><button type="button" class="button primary" data-media-consult>Plan this media workflow</button></div><div class="approval-rail">${item.steps.map(([label,status])=>`<span class="${status==='pending'?'pending':''}">${label}</span>`).join('')}</div></div>`;
  root.querySelector('[data-media-consult]').onclick=()=>openNamedService('Social Media, Reels & Content Production');
}
document.querySelectorAll('[data-media-view]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-media-view]').forEach(x=>x.setAttribute('aria-selected',String(x===button)));renderMediaLibrary(button.dataset.mediaView);track('media_library_viewed',{library:button.dataset.mediaView})}));

const systemBoundaries={CRM:['Relationship and lead orchestration','Authorized client and prospect records'],Company360:['Enterprise profile and KPI context','Role-based executive intelligence'],Urban360:['Connected operating workspace','Tenant-isolated organizational view'],HRIS:['Employee system of record','No public-site record duplication'],ATS:['Recruiting and candidate workflow','Consent and hiring-role boundaries'],Projects:['Delivery plans and accountable work','Client and engagement isolation'],Academy:['Role-aware learning access','Assignment and completion evidence'],Analytics:['Governed reporting and signals','Aggregation and privacy controls'],'UrbanOne / ODA':['Orchestrated decisions and assistance','Policy-controlled system actions']};
document.querySelectorAll('[data-system]').forEach(button=>button.addEventListener('click',()=>{const [title,boundary]=systemBoundaries[button.dataset.system]||['Governed connection','Authentication required'],root=document.querySelector('#system-live');document.querySelectorAll('[data-system]').forEach(x=>x.classList.toggle('active',x===button));root.innerHTML=`<span>${button.dataset.system.toUpperCase()} · ACCESS BOUNDARY</span><h3>${title}</h3><p>${boundary}. Access is evaluated by identity, role and organization; records remain in the source system.</p><button type="button" class="button light" data-system-login>Authenticate through Urban Gateway</button>`;root.querySelector('[data-system-login]').onclick=()=>openModal('login');track('gateway_system_selected',{system:button.dataset.system})}));

document.querySelectorAll('.map-pulse').forEach(pulse=>{pulse.setAttribute('tabindex','0');pulse.setAttribute('role','button');const activate=()=>{const key=({"North America":'north-america',"South America":'south-america',Europe:'europe',Africa:'africa',Asia:'asia',Oceania:'oceania'})[pulse.dataset.region];if(!key)return;document.querySelector(`[data-jurisdiction="${key}"]`)?.click();document.querySelector('#jurisdictions')?.scrollIntoView({behavior:'smooth',block:'start'})};pulse.addEventListener('click',activate);pulse.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}})});
renderIntelligenceDimension();renderJurisdiction();renderMediaLibrary();
